// spec: specs/customers-pricing.md §9 · кейсы .qa/tests/customers/cust-09, cust-10, cust-08 · несколько ролей (rep + admin) — пишется вручную (asUser)
// #a6af81 (עבר QA 29.10): у נציג מכירות («testtest», rep.json) в «לקוח חדש» тот же переключатель «יצירת קישור הצטרפות», что у מפיץ.
//   Вкл. → «יצירת לקוח וקישור הזמנה»: клиент + ссылка (POST customers, POST customer_invites), окно «החשבון נפתח»,
//   «העתקת קישור ההצטרפות» ставит sent_at (у admin статус «הוזמן»); кнопки «השלמת פרטי הלקוח» у נציג нет.
//   Клиент закреплён за создавшим נציג. RLS (migration 20261029120000_a_rep_mints_a_join_link): ссылки — только своим клиентам.
//   В «הזמנה מהודעה» окно «לקוח חדש» без переключателя у обеих ролей (сверено 29.10, не ошибка).
// #5a2dbd: у נציג статусы только «פעיל» / «מושבת» — клиент со ссылкой у него «פעיל».
// Данные: QA-AUTO-cust-a6af81-<ts>-*; ссылку копируем (только clipboard, никому не отправляем, по ней не регистрируемся);
//   afterAll — admin удаляет клиентов (ссылки удаляются вместе с клиентом).
import { randomUUID } from 'crypto';
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import {
  rowOf, openList, openListReady, search, openNewCustomer, rest, deleteCustomersByPrefix, openCardReady, cardTag,
  SUBTITLE_LINK, BTN_LINK, BTN_SAVE, SWITCH_LINK, ST_ACTIVE, ST_INVITED, ST_PENDING, ST_NO_CATALOG,
} from './_customers';

test.describe.configure({ mode: 'serial' });

const PREFIX = `QA-AUTO-cust-a6af81-${Date.now().toString().slice(-7)}`;
const LINKED = `${PREFIX}-link`;
let linkedId = '';

async function profileId(admin: Page, fullName: string) {
  const r = await rest(admin, 'GET', `profiles?select=id&role=eq.sales_rep&full_name=eq.${encodeURIComponent(fullName)}`);
  expect(r.status).toBe(200);
  expect(r.json, `נציג «${fullName}»`).toHaveLength(1);
  return r.json[0].id as string;
}

const isInvitesWrite = (method: string) => (r: { url(): string; request(): { method(): string } }) =>
  /\/rest\/v1\/customer_invites(\?|$)/.test(r.url()) && r.request().method() === method;

test.describe('customers — נציג יוצר לקוח עם קישור הצטרפות (#a6af81)', () => {
  test.afterAll(async ({ browser }) => {
    await deleteCustomersByPrefix(browser, test.info().project.use.baseURL, PREFIX);
  });

  test('נציג, מתג דלוק → «יצירת לקוח וקישור הזמנה»: לקוח + קישור, «החשבון נפתח» בלי «השלמת פרטי הלקוח», העתקה מסמנת «נשלח»; אצל הנציג «פעיל», אצל מנהל «הוזמן» ו«נציג מכירות: testtest» #a6af81 #5a2dbd @desktop @data', async ({ asUser }) => {
    const rep = await asUser('rep');
    await rep.context().grantPermissions(['clipboard-read', 'clipboard-write']);
    await openList(rep);
    const dlg = await openNewCustomer(rep);
    await expect(dlg.getByRole('switch', { name: SWITCH_LINK })).toHaveAttribute('aria-checked', 'true');
    await expect(dlg.getByText(SUBTITLE_LINK)).toBeVisible();
    await dlg.getByRole('textbox', { name: /^שם העסק/ }).fill(LINKED);
    await dlg.getByRole('textbox', { name: 'איש קשר' }).fill('QA bot');
    await dlg.getByRole('textbox', { name: 'טלפון' }).fill('0500000001');

    const [custResp, inviteResp] = await Promise.all([
      rep.waitForResponse((r) => /\/rest\/v1\/customers(\?|$)/.test(r.url()) && r.request().method() === 'POST'),
      rep.waitForResponse(isInvitesWrite('POST')),
      dlg.getByRole('button', { name: BTN_LINK }).click(),
    ]);
    // «מה רצוי» «מתג דלוק»: נוצר קישור הצטרפות שהנציג שולח ללקוח
    expect(custResp.status(), 'POST customers (נציג)').toBe(201);
    expect(inviteResp.status(), 'POST customer_invites (נציג, свой клиент)').toBe(201);
    const body = await custResp.json();
    linkedId = (Array.isArray(body) ? body[0] : body).id;

    // окно как у מפיץ: «החשבון נפתח», ссылка ещё не передана; «השלמת פרטי הלקוח» у נציג нет (комментарий программиста)
    await expect(dlg.getByRole('heading', { name: 'החשבון נפתח' })).toBeVisible({ timeout: 15_000 });
    await expect(dlg.getByText('נוצר קישור הצטרפות אך הוא טרם נמסר ללקוח.')).toBeVisible();
    await expect(dlg.getByRole('button', { name: 'השלמת פרטי הלקוח' })).toHaveCount(0);

    const [sent] = await Promise.all([
      rep.waitForResponse(isInvitesWrite('PATCH')),
      dlg.getByRole('button', { name: 'העתקת קישור ההצטרפות' }).click(),
    ]);
    expect(sent.status(), 'PATCH customer_invites (sent_at)').toBe(204);
    expect(JSON.parse(sent.request().postData() || '{}').sent_at, 'sent_at выставлен').toBeTruthy();
    await expect(dlg.getByText('הקישור הועתק ומוכן למסירה ללקוח.')).toBeVisible();
    await dlg.getByRole('button', { name: 'סגירה' }).click();
    await expect(rep.getByRole('dialog')).toHaveCount(0);

    // у נציג: клиент в его списке, статус «פעיל» (#5a2dbd: у נציג только «פעיל»/«מושבת»)
    const row = rowOf(rep, LINKED);
    await expect(row).toBeVisible({ timeout: 20_000 });
    await expect(row).toContainText(ST_ACTIVE);
    for (const s of [ST_PENDING, ST_NO_CATALOG, ST_INVITED]) await expect(row).not.toContainText(s);

    // у admin: ссылка отдана → «הוזמן»; закреплён за testtest («בשני המקרים הלקוח משויך אוטומטית לנציג שיצר אותו»)
    const admin = await asUser('admin');
    await openListReady(admin);
    await search(admin, LINKED);
    await expect(rowOf(admin, LINKED)).toContainText(ST_INVITED, { timeout: 20_000 });
    await openCardReady(admin, linkedId, LINKED);
    await expect(cardTag(admin, ST_INVITED)).toBeVisible();
    const repBox = admin.getByRole('main').locator('div').filter({ has: admin.getByText('נציג מכירות', { exact: true }) }).filter({ hasText: 'testtest' }).last();
    await expect(repBox).toBeVisible();
    const c = await rest(admin, 'GET', `customers?select=sales_rep_id&id=eq.${linkedId}`);
    expect(c.json?.[0]?.sales_rep_id, 'sales_rep_id = создавший נציג').toBe(await profileId(admin, 'testtest'));
    const inv = await rest(admin, 'GET', `customer_invites?select=sent_at,redeemed_at&customer_id=eq.${linkedId}`);
    expect(inv.json, 'одна ссылка, отдана, не использована').toHaveLength(1);
    expect(inv.json[0].sent_at).toBeTruthy();
    expect(inv.json[0].redeemed_at).toBeNull();
  });

  test('RLS: נציג לא יכול ליצור קישור הצטרפות ללקוח שאינו שלו — 403; רואה קישורים רק של הלקוחות שלו #a6af81 @desktop @data', async ({ asUser }) => {
    const admin = await asUser('admin');
    await openList(admin);
    const testtestId = await profileId(admin, 'testtest');
    const foreign = await rest(admin, 'GET', `customers?select=id,distributor_id&archived_at=is.null&or=(sales_rep_id.is.null,sales_rep_id.neq.${testtestId})&limit=1`);
    expect(foreign.json, 'есть чужой клиент').toHaveLength(1);
    const { id: foreignId, distributor_id: distributorId } = foreign.json[0];

    const rep = await asUser('rep');
    await openList(rep);
    const token = randomUUID();
    const r = await rest(rep, 'POST', 'customer_invites', {
      distributor_id: distributorId, customer_id: foreignId, token, email: null,
      expires_at: new Date(Date.now() + 7 * 864e5).toISOString(),
    });
    try {
      expect(r.status, `ответ ${JSON.stringify(r.json)}`).toBe(403);
      expect(r.json?.code).toBe('42501');
    } finally {
      // если вставка вдруг прошла — убрать мусорную ссылку
      if (r.status === 201) await rest(admin, 'DELETE', `customer_invites?token=eq.${token}`);
    }

    // чтение: только ссылки своих клиентов
    const own = await rest(rep, 'GET', 'customers?select=id');
    const ownIds = new Set((own.json as { id: string }[]).map((x) => x.id));
    const seen = await rest(rep, 'GET', 'customer_invites?select=customer_id');
    expect(seen.status).toBe(200);
    const alien = (seen.json as { customer_id: string }[]).filter((x) => !ownIds.has(x.customer_id));
    expect(alien, 'נציג не видит ссылки чужих клиентов').toEqual([]);
  });

  test('מנהל: ב«הזמנה מהודעה» חלון «לקוח חדש» בלי מתג — כמו אצל הנציג #a6af81 @desktop', async ({ asUser }) => {
    const admin = await asUser('admin');
    await admin.goto('/orders/new');
    await expect(admin.getByRole('heading', { level: 1, name: 'הזמנה מהודעה' })).toBeVisible({ timeout: 30_000 });
    const dlg = await openNewCustomer(admin);
    await expect(dlg.getByRole('switch')).toHaveCount(0);
    await expect(dlg.getByRole('button', { name: BTN_SAVE })).toBeVisible();
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(admin.getByRole('dialog')).toHaveCount(0);
  });
});
